    cast: ChartsCast(
      instant: blob.column(atCast, 0, 8, Float64List.sublistView),
      lagnaDeg: blob.column(atCast, 1, 8, Float64List.sublistView),
      dayLagnaDeg: blob.column(atCast, 2, 8, Float64List.sublistView),
      ayanamshaOffsetDeg: blob.column(atCast, 3, 8, Float64List.sublistView),
      dayPart: blob.column(atCast, 4, 1, Uint8List.sublistView),
      dayElapsed: blob.column(atCast, 5, 8, Float64List.sublistView),
      pointCount: blob.column(atCast, 6, 4, Uint32List.sublistView),
      aspectCount: blob.column(atCast, 7, 4, Uint32List.sublistView),
