/// The amrita kalam: each nakshatra's four auspicious ghatis, placed by `panchanga.amrit_kalam` (crux C677). `whole` is the window itself, four sixtieths of the star from the reading's ghati, and `inside` the part of it in the day; empty under `NONE`.
final class PanchangaAmritKalam {
  const PanchangaAmritKalam({
    required this.member,
    required this.wholeFrom,
    required this.wholeTo,
    required this.insideFrom,
    required this.insideTo,
    required this.sunrises,
    required this.endsGhati,
    required this.endsPala,
    required this.endsVipala,
    required this.length,
  });

  /// Whose amrita kalam it is.
  final Uint16List member;

  /// When the member itself began, as a Julian day (UTC), whether or not that is inside the day.
  final Float64List wholeFrom;

  /// When the member itself ended, as a Julian day (UTC), whether or not that is inside the day.
  final Float64List wholeTo;

  /// Where the part inside the day begins: what an almanac row prints.
  final Float64List insideFrom;

  /// Where the part inside the day ends.
  final Float64List insideTo;

  /// Which of the day's two sunrises the member was running at: its own, the next day's, both (vriddhi: it names two days) or neither (kshaya: it names none).
  final Uint8List sunrises;

  /// When the member ended, in ghatis from the day's sunrise under `day.ghati_reckoning`; a member outlasting the day reads as the day's whole count.
  final Uint8List endsGhati;

  /// And palas, 0 to 59.
  final Uint8List endsPala;

  /// And vipalas, 0 to 59.
  final Uint8List endsVipala;

  /// The number of rows every column holds.
  final int length;
}

/// The `lagnas` section of a Panchanga blob: one typed list per column, each a
/// view over the blob's bytes rather than a copy.
///
/// The lagna table, when `sections` asked for `TS_PANCHANGA_LAGNAS`: each sign rising from sunrise to the next sunrise, from the ascendant `panchanga.lagna_table` names (crux C680). `whole` is the sign's rising, which for the first and the last can begin before sunrise or end after the next, and `inside` the part of it in the day (C681). Empty when not asked for.
final class PanchangaLagnas {
  const PanchangaLagnas({
    required this.member,
    required this.wholeFrom,
    required this.wholeTo,
    required this.insideFrom,
    required this.insideTo,
    required this.sunrises,
    required this.endsGhati,
    required this.endsPala,
    required this.endsVipala,
    required this.length,
  });

  /// The sign rising.
  final Uint16List member;

  /// When the member itself began, as a Julian day (UTC), whether or not that is inside the day.
  final Float64List wholeFrom;

  /// When the member itself ended, as a Julian day (UTC), whether or not that is inside the day.
  final Float64List wholeTo;

  /// Where the part inside the day begins: what an almanac row prints.
  final Float64List insideFrom;

  /// Where the part inside the day ends.
  final Float64List insideTo;

  /// Which of the day's two sunrises the member was running at: its own, the next day's, both (vriddhi: it names two days) or neither (kshaya: it names none).
  final Uint8List sunrises;

  /// When the member ended, in ghatis from the day's sunrise under `day.ghati_reckoning`; a member outlasting the day reads as the day's whole count.
  final Uint8List endsGhati;

  /// And palas, 0 to 59.
  final Uint8List endsPala;

  /// And vipalas, 0 to 59.
  final Uint8List endsVipala;

  /// The number of rows every column holds.
  final int length;
}

/// A decoded Panchanga blob.
///
/// A batch of daily panchangas at one place: the day, the four moving limbs, the periods, the lunar month, what the Moon and the Sun did, and what the day is said to be. Every per-day list is concatenated across the batch, with `counts` saying how many rows are each day's.
final class Panchanga {
  const Panchanga({
    required this.dayCount,
    required this.latitudeDeg,
    required this.longitudeDeg,
    required this.altitudeM,
    required this.calendar,
    required this.lunarMonth,
    required this.days,
    required this.counts,
    required this.day,
    required this.tithi,
    required this.nakshatra,
    required this.yoga,
    required this.karana,
    required this.panchaka,
    required this.moonSigns,
    required this.sunSigns,
    required this.kaalas,
    required this.choghadiya,
    required this.horas,
    required this.muhurtas,
    required this.moonEvents,
    required this.muhurtaYogas,
    required this.model,
    required this.provenanceJson,
    required this.contentHashes,
    required this.muhurta,
    required this.festivals,
    required this.years,
    required this.eclipses,
    required this.nepalSambat,
    required this.varjyam,
    required this.nakshatraShool,
    required this.chandraVasa,
    required this.chandrashtama,
    required this.amritKalam,
    required this.lagnas,
  });

  /// How many days the batch holds, and how many rows the `days`, `counts` and `day` sections each hold.
  final int dayCount;

  /// The place's latitude, degrees north.
  final double latitudeDeg;

  /// The place's longitude, degrees east.
  final double longitudeDeg;

  /// The place's altitude, metres.
  final double altitudeM;

  /// The civil calendar the days' dates are read in.
  final int calendar;

  /// Which lunar-month convention `days.month` leads with.
  final int lunarMonth;

  /// One row per day: what the day is, beside the `day` section's account of the day it belongs to. Three values a day may not have — the sankranti, Abhijit and Brahma muhurta — carry a presence flag beside them rather than a sentinel, because an absent instant and midnight are both nought.
  final PanchangaDays days;

  /// How many rows of each per-day section belong to each day, in the order the days run. A day's rows begin where the sum of every earlier day's count leaves off.
  final PanchangaCounts counts;

  /// The day each instant belongs to: its arc, its date and how it was reckoned. One row per row of the blob's own grid.
  final Day day;

  /// The tithis that touch each day.
  final PanchangaTithi tithi;

  /// The nakshatras the Moon was in.
  final PanchangaNakshatra nakshatra;

  /// The nitya yogas.
  final PanchangaYoga yoga;

  /// The karanas; half-tithis, so there are three or four on an ordinary day.
  final PanchangaKarana karana;

  /// Panchaka, while the Moon is in the last five nakshatras.
  final PanchangaPanchaka panchaka;

  /// The signs the Moon stood in, with when it entered and left each.
  final PanchangaMoonSigns moonSigns;

  /// The signs the Sun stood in; two only on a sankranti day.
  final PanchangaSunSigns sunSigns;

  /// The inauspicious eighths of the daylight each day has.
  final PanchangaKaalas kaalas;

  /// Eight choghadiya of the daylight and eight of the night, when the day has both.
  final PanchangaChoghadiya choghadiya;

  /// The twenty-four horas of each day, from sunrise.
  final PanchangaHoras horas;

  /// The thirty muhurtas of each day: fifteen of the daylight and fifteen of the night that follows it, in order. Abhijit and Brahma muhurta are named in `days` rather than repeated here.
  final PanchangaMuhurtas muhurtas;

  /// Every moonrise and moonset inside each day's moon window, in order.
  final PanchangaMoonEvents moonEvents;

  /// The muhurta yogas that held, with what made each hold. `because_*` is a tagged enum split into a kind and the payload fields of its widest variant, so a `VARA_NAKSHATRA` cause leaves `because_tithi` at zero.
  final PanchangaMuhurtaYogas muhurtaYogas;

  /// UTF-8 text: the solar model that reckoned the days, as it describes itself.
  final String model;

  /// UTF-8 JSON: the provenance envelope of the result, canonical.
  final String provenanceJson;

  /// UTF-8 text: each day's own content hash — its panchanga, canonical — as sixty-four lowercase hex digits, a day after the other in the batch's order with nothing between them, so day `i` is bytes `64 * i` to `64 * i + 64`. The provenance's `content_hash` is the list's; a day handed out alone carries its own (`03-design/serial-and-the-envelope.md` §3).
  final String contentHashes;

  /// UTF-8 JSON, canonical: the muhurta search `muhurta_json` asked for over these days, as its envelope `{value, provenance}` (`03-design/muhurta-at-the-boundary.md`). `value` is `{windows, closed, daysJudged, daysCut, windowsBlackedOut, ranking, unjudged}`: each window `{at, clauses, barredBy, score}`, an interval `{from, to}` in UTC Julian days, every clause `{clause, at, ...}` tagged by its kind with that kind's fields beside the tag, `barredBy` the bars that struck it (a clause's key or a clause), and `score` the baseline's `{value, factors, cappedAt}` under the `BASELINE` ranking, else null; each closed day `{date, by}`, the blackouts that closed it. Every catalogue member is written as its full key (`nakshatra.ROHINI`), and the envelope is sealed over exactly this value. Empty when `muhurta_json` asked for none.
  final String muhurta;

  /// UTF-8 JSON, canonical: the days the rules `festivals_json` asked for fall on over these days, as the envelope `{value, provenance}` (`03-design/festival-rules.md` §7). `value` is `{observances, ekadashis, unjudged}`, `dated` beside them when a rule kept on a date gave a day, and `anniversaries` when the request named one: each observance `{rule, day, tithi, month, adhika, case, extents, decidedBy, choice, marginSeconds, parana}`, the rule's key, the calendar date it falls on, the occurrence judged `{from, to}` in UTC Julian days (the tithi's, or the nakshatra's for a rule kept on one), its amanta month as a full key and whether that month is adhika, the case between its two days (`EARLIER_ONLY`, `LATER_ONLY`, `BOTH`, `NEITHER`, `EQUAL_PARTS`, `UNEQUAL_PARTS`), each day's extent `{day, window, held}`, `decidedBy` `{by: GUARD, index}`, `{by: OTHERWISE}` or, for a rule counted from another's day, `{by: AFTER, rule, days}` (its tithi, case and extents then the counted-from observance's), the choice that decided (`EARLIER`, `LATER` or `BY_YUGMA`, which `day` resolves), and the seconds of time every instant the day was decided from (the two sunrises, the next, the windows the rule and its guards draw) may move, as a different place moves them, before the day can change: 0 for two equal parts; and, for a rule whose fast is broken by a reading (§8.7), each reading answered `{reading, day, from, fromBy, to, toBy}`, the rule's reading as it spells it (`TITHI_END`, `WITHIN`, `SUNRISE`, `AFTER_WINDOW`, `NEXT_TITHI`, `AFTER_RITE` with its `rite` and `remnant`), the day the meal falls on (the day after for most, the fast day for a reading ending on it, the rite's day after a rite), when the meal may begin, what set it (`SUNRISE`, `TITHI_END`, `NAKSHATRA_END`, `YAMAS`, `WINDOW_END`, `RITE`), and when it must be taken by and what set that (absent when the reading sets no end); each Ekadashi fast `{rule, tithi, month, adhika, tithis, days, piercedAt, pierced, excess, choice, day, marginSeconds, parana, mahadvadashi}`, the rule's key, the 11th and its lunar month as full keys, whether that month is adhika, the 10th, the 11th and the 12th as `{from, to}`, the 11th's own day and the next, where the 10th reached into the 11th's day (`SUNRISE`, `ARUNODAYA` or null), whether that counts under the rule's vedha, which of the 11th and the 12th holds the next sunrise (`ELEVENTH`, `TWELFTH`, `BOTH`, `NEITHER`), the choice (`EARLIER` or `LATER`, which `day` resolves unless a mahadvadashi moved it, perhaps to the day after both), and the seconds of time every instant the fast was decided from (the sunsets that give the 11th its own day, that day's sunrise and, under a Vaishnava vedha, its arunodaya, and the two sunrises after) may move before the day can change, and, for a rule with a parana, when the fast is broken (§8.5): `{day, tithi, hariVasaraEnds, kept, barred}`, the day after the fast, the tithi the meal is kept in as a full key, when the 12th's first quarter ends if after that day's sunrise (else null), the window kept `{span, at, fromBy, toBy}` (null when none of the rule's leaves time), `at` the rule's window as it spells it and each edge's clause `WINDOW`, `HARI_VASARA`, `TITHI_START`, `TITHI_END`, `NAKSHATRA` or `JOINED_NAKSHATRA`, and, for a rule whose parana lists `bars` (C700) when one met that day's daylight, `barred` `{bar, span, setAside}`: the bar `{tithi, month, nakshatra, portion}` as the rule spells it (`portion` `{parts, which}`, absent for the whole nakshatra), the Moon's stay in the barred share, and whether the bar was set aside because the share outlasts the tithi the meal is kept in; and, for a rule keeping mahadvadashis (§8.9) when one held, `mahadvadashi` `{kind, held, clause, joined}`: the kind that set the day (`UNMILANI`, `VYANJULI`, `TRISPRISHA`, `PAKSHAVARDHINI`, `JAYA`, `VIJAYA`, `JAYANTI`, `PAPANASHINI`), every kind that held in the rule's order, the verse that defines it, and for the four nakshatra kinds the joined nakshatra `{nakshatra, span}`, a full key and its whole stay; each unjudged occurrence `{rule, tithi, why}`; each dated day `{rule, day, on}`, the rule's key, the day, and the same day in the rule's own calendar (`calendar.BIKRAM_SAMBAT` for a sankranti); each anniversary's day (`03-design/shraddha.md`) `{key, count, kind, origin, monthBy, observance}`, the request's key, which anniversary it is (1 for the first recurrence, a janma tithi's the age turned, absent for a lunar origin given no moment), the kind kept (`EKODDISHTA`, `PARVANA`, `JANMA_TITHI`), the origin as found `{tithi, month, kind, half, nakshatra, at, assumedSunrise, candidates}` (the tithi and amanta month as full keys, the lunation's `NIJA`, `ADHIKA` or `KSHAYA`, the tithi's `FIRST` or `SECOND` half, the nakshatra then as a full key, the moment as a UTC Julian day, whether the tithi is a date's sunrise tithi for want of an hour, and every tithi the date held when more than one), the clause that chose the month (`NIJA`, `FIRST_YEAR_ADHIKA`, `ADHIKA_ORIGIN`, `KSHAYA_JOINED`), and the day as an observance. A date's calendar and era are written as full keys (`calendar.GREGORIAN`), and the envelope is sealed over exactly this value; its provenance names the widened days as `festival.days`. Empty when `festivals_json` asked for none.
  final String festivals;

  /// UTF-8 JSON, canonical: the lunar years these days fall in when `sections` asked for `TS_PANCHANGA_YEARS`, as the envelope `{value, provenance}` (`03-design/calendar-indian-lunisolar.md` §10). `value` is a list of years in order, each `{samvatsara, count, vikrama, shaka, opened, began, ended, jovian, lupta}`: the name the year carries as a full key (`samvatsara.PRAMADICHA`), the count that named it under `calendars.samvatsara` (`BARHASPATYA`, `BARHASPATYA_RUNNING`, `CHANDRAMANA`), its Vikrama and Shaka numbers, the new moon that opened its first Chaitra, the sunrise of Chaitra Shukla Pratipada that began it and the next year's that ended it, in UTC Julian days; the Jovian years that ran in it, each `{member, count, from, to}` with its member in full, the signs mean Jupiter had crossed since the Kali age began, counted from 0, and its bounds in UTC Julian days; and the Jovian year expunged in it, in full, or null. Consecutive years abut, `ended` to `began`. Empty when `sections` did not ask for them.
  final String years;

  /// UTF-8 JSON, canonical: the eclipses whose greatest moment falls between the first day's local midnight and the midnight after the last, when `sections` asked for `TS_PANCHANGA_ECLIPSES`, as the envelope `{value, provenance}` (`03-design/eclipses.md`). `value` is `{lunar, solar}`, each a list in order of `{eclipse, here}`. A lunar `eclipse` is `{greatest, kind, gamma, umbralMagnitude, penumbralMagnitude, contacts, shadow}`: the kind `PENUMBRAL`, `PARTIAL` or `TOTAL`, gamma in Earth radii, the contacts `{p1, u1, u2, u3, u4, p4}` with the umbral ones null where the eclipse lacks them, and the shadow rule it was read under (`DANJON`, `CHAUVENET`, from `panchanga.eclipse_shadow`); its `here` is `{p1, u1, u2, greatest, u3, u4, p4, seen, umbralSeen}`, each moment `{at, altitudeDeg}` with the Moon's topocentric geometric altitude there, and `umbralSeen` the stretch of the umbral phase seen, or null. A solar `eclipse` is `{greatest, kind, gamma, magnitude, point}`: the kind `PARTIAL`, `ANNULAR`, `TOTAL` or `HYBRID`, and the point of greatest eclipse `{latitude, longitude}` in degrees; its `here` is null where the Moon's disc never touches the Sun's from the place, else `{kind, magnitude, obscuration, first, second, third, fourth, maximum, seen}`, the place's own contacts with the Sun's altitude at each, the second and third null outside a central path. `seen` is `{from, to}`, the stretch of the eclipse the body stands above `panchanga.eclipse_horizon`'s horizon, or null where the place does not see it. Every instant is a UT1 Julian day, UTC to within a second. Empty when `sections` did not ask for them.
  final String eclipses;

  /// UTF-8 JSON, canonical: each day's Nepal Sambat date when `sections` asked for `TS_PANCHANGA_NEPAL_SAMBAT`, as the envelope `{value, provenance}` (`03-design/calendar-indian-lunisolar.md` §11). `value` is a list in the days' order, each `{year, month, kind, paksha}`: the year, which opens at Kachhala's first day (1146 from 2025-10-22); the month, 1 for Kachhala (amanta Kartika) to 12 for Kaula (amanta Ashwina), an adhika month keeping the number of the month it repeats; the month's kind (`NIJA`, `ADHIKA`, which is Anala, or `KSHAYA`); and the half as a full key, `paksha.SHUKLA` (thwa) or `paksha.KRISHNA` (ga). The provenance is the days' own. Empty when `sections` did not ask for them.
  final String nepalSambat;

  /// The varjyam: each nakshatra's four ghatis of poison, placed by `panchanga.varjyam` (crux C165). `whole` is the window itself, four sixtieths of the star from the table's ghati, and `inside` the part of it in the day; empty under `NONE`.
  final PanchangaVarjyam varjyam;

  /// The nakshatra shool: while the Moon is in one of the four nakshatras that block a direction, that direction (Muhurta Chintamani, Yatra Prakarana v. 10, crux C402). Empty on a day the Moon crosses none of the four. The vara's own direction is `days.disha_shool`.
  final PanchangaNakshatraShool nakshatraShool;

  /// The chandra vasa: the direction the Moon dwells in, by the sign it stands in (the commentary's sign directions on Yatra Prakarana v. 34, crux C403), one span for each sign the Moon stood in over the day.
  final PanchangaChandraVasa chandraVasa;

  /// Whose chandrashtama the day holds (Kalaprakasika, the eighth sign counted inclusively, crux C404): the member is a **natal** Moon sign, and the intervals are the Moon's own run through the eighth sign from it.
  final PanchangaChandrashtama chandrashtama;

  /// The amrita kalam: each nakshatra's four auspicious ghatis, placed by `panchanga.amrit_kalam` (crux C677). `whole` is the window itself, four sixtieths of the star from the reading's ghati, and `inside` the part of it in the day; empty under `NONE`.
  final PanchangaAmritKalam amritKalam;

  /// The lagna table, when `sections` asked for `TS_PANCHANGA_LAGNAS`: each sign rising from sunrise to the next sunrise, from the ascendant `panchanga.lagna_table` names (crux C680). `whole` is the sign's rising, which for the first and the last can begin before sunrise or end after the next, and `inside` the part of it in the day (C681). Empty when not asked for.
  final PanchangaLagnas lagnas;

}

/// Decodes a Panchanga blob. The columns are views over `bytes`, so the
/// buffer must outlive the result; a blob of another layout version or
/// another schema is a [FormatException].
Panchanga decodePanchanga(Uint8List bytes) {
  final blob = _Blob.open(bytes, 4, 'panchanga');
  final atSummary = blob.fixed(1, 'summary', 6);
  final atDays = blob.section(2, 'days');
  final atCounts = blob.section(3, 'counts');
  final atDay = blob.section(4, 'day');
  final atTithi = blob.section(5, 'tithi');
  final atNakshatra = blob.section(6, 'nakshatra');
  final atYoga = blob.section(7, 'yoga');
  final atKarana = blob.section(8, 'karana');
  final atPanchaka = blob.section(9, 'panchaka');
  final atMoonSigns = blob.section(10, 'moon_signs');
  final atSunSigns = blob.section(11, 'sun_signs');
  final atKaalas = blob.section(12, 'kaalas');
  final atChoghadiya = blob.section(13, 'choghadiya');
  final atHoras = blob.section(14, 'horas');
  final atMuhurtas = blob.section(15, 'muhurtas');
  final atMoonEvents = blob.section(16, 'moon_events');
  final atMuhurtaYogas = blob.section(17, 'muhurta_yogas');
  final atModel = blob.section(18, 'model');
  final atProvenanceJson = blob.section(19, 'provenance_json');
  final atContentHashes = blob.section(20, 'content_hashes');
  final atMuhurta = blob.section(21, 'muhurta');
  final atFestivals = blob.section(22, 'festivals');
  final atYears = blob.section(23, 'years');
  final atEclipses = blob.section(24, 'eclipses');
  final atNepalSambat = blob.section(25, 'nepal_sambat');
  final atVarjyam = blob.section(26, 'varjyam');
  final atNakshatraShool = blob.section(27, 'nakshatra_shool');
  final atChandraVasa = blob.section(28, 'chandra_vasa');
  final atChandrashtama = blob.section(29, 'chandrashtama');
  final atAmritKalam = blob.section(30, 'amrit_kalam');
  final atLagnas = blob.section(31, 'lagnas');
  return Panchanga(
    dayCount: blob.data.getUint32(atSummary.offset + 0, Endian.little),
    latitudeDeg: blob.data.getFloat64(atSummary.offset + 8, Endian.little),
    longitudeDeg: blob.data.getFloat64(atSummary.offset + 16, Endian.little),
    altitudeM: blob.data.getFloat64(atSummary.offset + 24, Endian.little),
    calendar: blob.data.getUint16(atSummary.offset + 32, Endian.little),
    lunarMonth: blob.data.getUint8(atSummary.offset + 40),
    days: PanchangaDays(
      windowFrom: blob.column(atDays, 0, 8, Float64List.sublistView),
      windowTo: blob.column(atDays, 1, 8, Float64List.sublistView),
      month: blob.column(atDays, 2, 2, Uint16List.sublistView),
      amanta: blob.column(atDays, 3, 2, Uint16List.sublistView),
      purnimanta: blob.column(atDays, 4, 2, Uint16List.sublistView),
      paksha: blob.column(atDays, 5, 2, Uint16List.sublistView),
      monthKind: blob.column(atDays, 6, 1, Uint8List.sublistView),
      ayana: blob.column(atDays, 7, 2, Uint16List.sublistView),
      ritu: blob.column(atDays, 8, 2, Uint16List.sublistView),
      dishaShool: blob.column(atDays, 9, 2, Uint16List.sublistView),
      hasSankranti: blob.column(atDays, 10, 1, Uint8List.sublistView),
      sankranti: blob.column(atDays, 11, 8, Float64List.sublistView),
      hasAbhijit: blob.column(atDays, 12, 1, Uint8List.sublistView),
      abhijitFrom: blob.column(atDays, 13, 8, Float64List.sublistView),
      abhijitTo: blob.column(atDays, 14, 8, Float64List.sublistView),
      abhijitEffective: blob.column(atDays, 15, 1, Uint8List.sublistView),
      hasBrahma: blob.column(atDays, 16, 1, Uint8List.sublistView),
      brahmaFrom: blob.column(atDays, 17, 8, Float64List.sublistView),
      brahmaTo: blob.column(atDays, 18, 8, Float64List.sublistView),
      moonWindowFrom: blob.column(atDays, 19, 8, Float64List.sublistView),
      moonWindowTo: blob.column(atDays, 20, 8, Float64List.sublistView),
      length: atDays.count,
    ),
    counts: PanchangaCounts(
      tithi: blob.column(atCounts, 0, 4, Uint32List.sublistView),
      nakshatra: blob.column(atCounts, 1, 4, Uint32List.sublistView),
      yoga: blob.column(atCounts, 2, 4, Uint32List.sublistView),
      karana: blob.column(atCounts, 3, 4, Uint32List.sublistView),
      panchaka: blob.column(atCounts, 4, 4, Uint32List.sublistView),
      moonSigns: blob.column(atCounts, 5, 4, Uint32List.sublistView),
      sunSigns: blob.column(atCounts, 6, 4, Uint32List.sublistView),
      kaalas: blob.column(atCounts, 7, 4, Uint32List.sublistView),
      choghadiya: blob.column(atCounts, 8, 4, Uint32List.sublistView),
      horas: blob.column(atCounts, 9, 4, Uint32List.sublistView),
      muhurtas: blob.column(atCounts, 10, 4, Uint32List.sublistView),
