/// The `naam_names` section of a Naam blob: one typed list per column, each a
/// view over the blob's bytes rather than a copy.
///
/// Each name's first syllable, two rows: the bride's, then the groom's.
final class NaamNaamNames {
  const NaamNaamNames({
    required this.cell,
    required this.nakshatra,
    required this.abhijit,
    required this.quarter,
    required this.varga,
    required this.length,
  });

  /// Its place among the cakra's 112 cells, 0 for a, Krittika's first.
  final Uint8List cell;

  /// Its star; read only when `abhijit` is 0.
  final Uint16List nakshatra;

  /// 1 when the syllable is Abhijit's, which is none of the 27 (C292).
  final Uint8List abhijit;

  /// Which of the star's four syllables, 1 to 4: the pada, for one of the 27.
  final Uint8List quarter;

  /// The varga of the name's first letter as written (C295).
  final Uint8List varga;

  /// The number of rows every column holds.
  final int length;
}

/// A decoded Naam blob.
///
/// Two names matched star to star (naam milan): each name's first syllable in the śatapada cakra, the varga koota, and the Ashta Koota and the ten considerations read from the two name stars, in the same sections and shapes a chart's match crosses as.
final class Naam {
  const Naam({
    required this.naamNames,
    required this.relation,
    required this.matchings,
    required this.matchingKootas,
    required this.poruthams,
    required this.poruthamRows,
  });

  /// Each name's first syllable, two rows: the bride's, then the groom's.
  final NaamNaamNames naamNames;

  /// One varga, enemies (each the 5th from the other) or neither.
  final int relation;

  /// The Ashta Koota of the two name stars, as a chart's match reads two Moons. One row: the two names' match.
  final Matchings matchings;

  /// The eight kootas' points, in the verse's order.
  final MatchingKootas matchingKootas;

  /// The ten considerations of the two name stars. One row: the two names' match.
  final Poruthams poruthams;

  /// The ten considerations, in the chapter's order.
  final PoruthamRows poruthamRows;

}

/// Decodes a Naam blob. The columns are views over `bytes`, so the
/// buffer must outlive the result; a blob of another layout version or
/// another schema is a [FormatException].
Naam decodeNaam(Uint8List bytes) {
  final blob = _Blob.open(bytes, 5, 'naam');
  final atNaamNames = blob.section(1, 'naam_names');
  final atNaamVarga = blob.fixed(2, 'naam_varga', 1);
  final atMatchings = blob.section(3, 'matchings');
  final atMatchingKootas = blob.section(4, 'matching_kootas');
  final atPoruthams = blob.section(5, 'poruthams');
  final atPoruthamRows = blob.section(6, 'porutham_rows');
  return Naam(
    naamNames: NaamNaamNames(
      cell: blob.column(atNaamNames, 0, 1, Uint8List.sublistView),
      nakshatra: blob.column(atNaamNames, 1, 2, Uint16List.sublistView),
      abhijit: blob.column(atNaamNames, 2, 1, Uint8List.sublistView),
      quarter: blob.column(atNaamNames, 3, 1, Uint8List.sublistView),
      varga: blob.column(atNaamNames, 4, 1, Uint8List.sublistView),
      length: atNaamNames.count,
    ),
    relation: blob.data.getUint8(atNaamVarga.offset + 0),
    matchings: Matchings(
      total: blob.column(atMatchings, 0, 8, Float64List.sublistView),
      brideVarna: blob.column(atMatchings, 1, 2, Uint16List.sublistView),
      groomVarna: blob.column(atMatchings, 2, 2, Uint16List.sublistView),
      vashya: blob.column(atMatchings, 3, 1, Uint8List.sublistView),
      taraBrideToGroom: blob.column(atMatchings, 4, 1, Uint8List.sublistView),
      taraGroomToBride: blob.column(atMatchings, 5, 1, Uint8List.sublistView),
      brideYoni: blob.column(atMatchings, 6, 2, Uint16List.sublistView),
      groomYoni: blob.column(atMatchings, 7, 2, Uint16List.sublistView),
      yoni: blob.column(atMatchings, 8, 1, Uint8List.sublistView),
      brideLord: blob.column(atMatchings, 9, 2, Uint16List.sublistView),
      groomLord: blob.column(atMatchings, 10, 2, Uint16List.sublistView),
      maitri: blob.column(atMatchings, 11, 1, Uint8List.sublistView),
      maitriLifted: blob.column(atMatchings, 12, 1, Uint8List.sublistView),
      brideGana: blob.column(atMatchings, 13, 2, Uint16List.sublistView),
      groomGana: blob.column(atMatchings, 14, 2, Uint16List.sublistView),
      ganaDosha: blob.column(atMatchings, 15, 1, Uint8List.sublistView),
      ganaLifted: blob.column(atMatchings, 16, 1, Uint8List.sublistView),
      bhakootApart: blob.column(atMatchings, 17, 1, Uint8List.sublistView),
      bhakootDosha: blob.column(atMatchings, 18, 1, Uint8List.sublistView),
      bhakootOneLord: blob.column(atMatchings, 19, 1, Uint8List.sublistView),
      bhakootLordsFriends: blob.column(atMatchings, 20, 1, Uint8List.sublistView),
      bhakootNavamshaLordsFriends: blob.column(atMatchings, 21, 1, Uint8List.sublistView),
      bhakootTaraPure: blob.column(atMatchings, 22, 1, Uint8List.sublistView),
      bhakootVashya: blob.column(atMatchings, 23, 1, Uint8List.sublistView),
      bhakootLifted: blob.column(atMatchings, 24, 1, Uint8List.sublistView),
      brideNadi: blob.column(atMatchings, 25, 2, Uint16List.sublistView),
      groomNadi: blob.column(atMatchings, 26, 2, Uint16List.sublistView),
      nadiDosha: blob.column(atMatchings, 27, 1, Uint8List.sublistView),
      nadiLifted: blob.column(atMatchings, 28, 1, Uint8List.sublistView),
      length: atMatchings.count,
    ),
    matchingKootas: MatchingKootas(
      koota: blob.column(atMatchingKootas, 0, 2, Uint16List.sublistView),
      points: blob.column(atMatchingKootas, 1, 8, Float64List.sublistView),
      maxPoints: blob.column(atMatchingKootas, 2, 8, Float64List.sublistView),
      length: atMatchingKootas.count,
    ),
    poruthams: Poruthams(
      agreeing: blob.column(atPoruthams, 0, 1, Uint8List.sublistView),
      chiefAgreeing: blob.column(atPoruthams, 1, 1, Uint8List.sublistView),
      oneLord: blob.column(atPoruthams, 2, 1, Uint8List.sublistView),
      lordsFriendly: blob.column(atPoruthams, 3, 1, Uint8List.sublistView),
